use vstd::prelude::*;

verus! {

/// Simple interval type used by ChebyshevPoly.
/// (Fields are `i32` to match the default [-1, 1] requirement.)
pub struct Interval {
    pub min: i32,
    pub max: i32,
}

pub struct ChebyshevPoly {
    /// Chebyshev coefficients, stored as i32.
    pub coef: Vec<i32>,
    /// Domain interval for evaluation / interpretation.
    pub domain: Interval,
    /// Window interval (e.g., for mapping/scaling).
    pub window: Interval,
}

/// Interval validity predicate required by the problem statement.
pub open spec fn interval_valid(i: Interval) -> bool {
    i.min < i.max
}

/// Default interval constant required by the problem statement.
pub open spec fn default_interval() -> Interval {
    Interval { min: -1, max: 1 }
}

/// Specification-level conversion of a sequence of i8 coefficients to i32,
/// preserving length and order.
pub open spec fn coef_i8_to_i32(s: Seq<i8>) -> Seq<i32>
    decreases s.len()
{
    if s.len() == 0 {
        Seq::<i32>::empty()
    } else {
        coef_i8_to_i32(s.drop_last()).push(s.last() as i32)
    }
}

fn chebyshev(coef: Vec<i8>) -> (result: ChebyshevPoly)
    requires
        coef.len() > 0,
    ensures
        result.coef@ == coef_i8_to_i32(coef@),
        result.coef.len() == coef.len(),

        result.domain == default_interval(),
        interval_valid(result.domain),

        result.window == default_interval(),
        interval_valid(result.window),
{
    let n = coef.len();
    let mut out: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            0 <= i <= n,
            n == coef.len(),
            out.len() == i,
            out@ == coef_i8_to_i32(coef@.subrange(0, i as int)),
        decreases n - i,
    {
        let v_i8: i8 = coef[i];
        out.push(v_i8 as i32);
        i = i + 1;

        // After increment, show the invariant shape for the new i.
        assert(out@ == coef_i8_to_i32(coef@.subrange(0, i as int)));
    }

    // At loop exit, i == n, so the subrange is the whole sequence.
    assert(i == n);
    assert(coef@.subrange(0, n as int) == coef@);
    assert(out@ == coef_i8_to_i32(coef@));

    let d = default_interval();
    assert(interval_valid(d)); // -1 < 1

    ChebyshevPoly { coef: out, domain: d, window: d }
}

} // verus!

